/* re_init_data_game — native only.  Copies each table value into its variable if the variable is still
   all-zero (so values already set by re_init_consts or the data image win).  Returns how many were applied. */
int re_init_data_game(void) {   /* → число применённых значений */
  int n = 0; static const uint8_t z[8];
  for (unsigned i = 0; i < sizeof k_dinit / sizeof k_dinit[0]; i++)
    if (memcmp(k_dinit[i].p, z, k_dinit[i].n) == 0) { memcpy(k_dinit[i].p, k_dinit[i].b, k_dinit[i].n); n++; }
  return n;
}
